<script setup lang="ts">
const{me,working,notice,api,refreshMe,task}=useShowUp()
const step=ref(1),now=new Date(Date.now()+86400000)
const local=(d:Date)=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)
const form=reactive({title:'',starts:local(now),ends:local(new Date(now.getTime()+7200000)),capacity:20,paymentMode:'REFUNDABLE_DEPOSIT',amountNim:'1',participantCancellationPolicy:'REFUND_BEFORE_CUTOFF',cutoff:local(new Date(now.getTime()-3600000)),checkOpen:local(now),checkClose:local(new Date(now.getTime()+7200000)),deadline:local(new Date(now.getTime()+86400000))})
onMounted(refreshMe)
watch(()=>form.paymentMode, mode=>{if(mode==='REFUNDABLE_DEPOSIT')form.participantCancellationPolicy='REFUND_BEFORE_CUTOFF'})
function fillTest(){const n=Date.now();form.starts=local(new Date(n+600000));form.ends=local(new Date(n+2400000));form.cutoff=local(new Date(n+540000));form.checkOpen=form.starts;form.checkClose=form.ends;form.deadline=local(new Date(n+4200000))}
async function create(){
  let created:any
  try{
    await task('Creating event',async()=>{
      if(!/^(?:0|[1-9]\d*)(?:\.\d{1,5})?$/.test(form.amountNim))throw new Error('Enter a NIM amount with at most five decimal places.')
      const amountLuna=Math.round(Number(form.amountNim)*100000)
      if(amountLuna<=0||amountLuna>1000000)throw new Error('Enter an amount greater than zero and no more than 10 NIM.')
      const body={title:form.title,capacity:form.capacity,paymentMode:form.paymentMode,amountLuna,deposit:amountLuna,participantCancellationPolicy:form.participantCancellationPolicy,startsAt:+new Date(form.starts),endsAt:+new Date(form.ends),checkInOpensAt:+new Date(form.checkOpen),checkInClosesAt:+new Date(form.checkClose),cancellationCutoff:+new Date(form.cutoff),decisionDeadline:+new Date(form.deadline)}
      created=await api<any>('/api/events',{method:'POST',body})
      await api(`/api/events/${created.id}/open`,{method:'POST'})
    })
  }catch{if(!created)return}
  // A failed open leaves a saved draft. Continue there instead of creating duplicates.
  await navigateTo(`/host/e/${created.id}`)
}
</script>
<template><div class="shell"><AppHeader host><WalletButton/></AppHeader><div class="page-head"><p>Create event</p><h1>Set the promise once.</h1><p>Registration locks the payment and settlement terms shown to attendees.</p></div><div class="steps" aria-label="Creation progress"><span v-for="n in 3" :key="n" :class="{active:n<=step}"></span></div><StatusNotice v-if="notice" :tone="notice.tone" :title="notice.title" :message="notice.message"/><section v-if="step===1" class="panel"><h2>Event</h2><label class="field">Title<input v-model="form.title" maxlength="120"></label><label class="field">Start<input v-model="form.starts" type="datetime-local"></label><label class="field">End<input v-model="form.ends" type="datetime-local"></label><label class="field">Capacity<input v-model.number="form.capacity" type="number" min="1" max="20"><small>Between 1 and 20 seats.</small></label></section><section v-else-if="step===2" class="panel"><h2>Payment policy</h2><div class="option-grid"><label class="option" :class="{selected:form.paymentMode==='REFUNDABLE_DEPOSIT'}"><input v-model="form.paymentMode" type="radio" value="REFUNDABLE_DEPOSIT"><strong>Refundable deposit</strong><span>Attendees receive their deposit after a valid check-in.</span></label><label class="option" :class="{selected:form.paymentMode==='PAID_ADMISSION'}"><input v-model="form.paymentMode" type="radio" value="PAID_ADMISSION"><strong>Paid admission</strong><span>Attendees pay for a seat. Check-in consumes the ticket.</span></label></div><label class="field">{{ form.paymentMode==='PAID_ADMISSION'?'Ticket price':'Deposit' }} in NIM<input v-model="form.amountNim" inputmode="decimal"></label><label class="field">Participant cancellation<select v-model="form.participantCancellationPolicy"><option value="REFUND_BEFORE_CUTOFF">Refund before cutoff</option><option v-if="form.paymentMode==='PAID_ADMISSION'" value="NON_REFUNDABLE">Nonrefundable</option></select></label><label class="field">Cancellation cutoff<input v-model="form.cutoff" type="datetime-local"></label></section><section v-else class="panel"><h2>Check-in and review</h2><label class="field">Check-in opens<input v-model="form.checkOpen" type="datetime-local"></label><label class="field">Check-in closes<input v-model="form.checkClose" type="datetime-local"></label><label class="field">Decision deadline<input v-model="form.deadline" type="datetime-local"></label><article class="ticket"><div class="ticket-main"><EventPolicyBadge :mode="form.paymentMode"/><h2>{{ form.title || 'Untitled event' }}</h2><MoneyAmount :luna="Math.round(Number(form.amountNim)*100000)"/><p>{{ form.capacity }} seats. {{ form.participantCancellationPolicy==='NON_REFUNDABLE'?'Participant cancellation is nonrefundable.':'Refund before the cutoff.' }}</p><StatusNotice tone="waiting" title="Terms lock when registration opens" message="Price, payment mode, capacity, dates, check-in and settlement policy cannot be changed afterward."/></div><div class="ticket-stub"><span>ShowUp custody</span><strong>{{ form.paymentMode==='REFUNDABLE_DEPOSIT'?'Deposit held until settlement':'Admission revenue retained after use' }}</strong></div></article></section><BottomActionBar><div style="display:flex;gap:8px"><button v-if="step>1" class="secondary" @click="step--">Back</button><button v-if="step<3" :disabled="step===1&&!form.title" @click="step++">Continue</button><button v-else :disabled="!!working||!me?.organizer" @click="create">{{ working || 'Create and open registration' }}</button><button v-if="step===1" class="secondary" @click="fillTest">Fill test schedule</button></div></BottomActionBar></div></template>
